<?php get_header(); ?><main><section class="dn-wrap dn-hero"><h1><?php echo esc_html(get_theme_mod('dealnest_hero_title','Smart products. Better deals.')); ?></h1><p><?php echo esc_html(get_theme_mod('dealnest_hero_text','Affiliate products with photos, videos, descriptions and direct shopping links.')); ?></p></section><div class="dn-wrap dn-main"><aside class="dn-side"><h3>Categories</h3><?php $terms=get_terms(array('taxonomy'=>'product_category','hide_empty'=>true)); if(!is_wp_error($terms)) foreach($terms as $term) echo '<a href="'.esc_url(get_term_link($term)).'">'.esc_html($term->name).'</a>'; ?></aside><section><div class="dn-toolbar"><h2>Latest Products</h2></div><div class="dn-grid"><?php $q=new WP_Query(array('post_type'=>'affiliate_product','posts_per_page'=>12,'paged'=>max(1,get_query_var('paged')))); if($q->have_posts()): while($q->have_posts()):$q->the_post(); get_template_part('template-parts/product-card'); endwhile; else: echo '<p>No products added yet.</p>'; endif; wp_reset_postdata(); ?></div></section></div></main><?php get_footer(); ?>
